// server/services/geneticPromptMutationEngine.ts
var MUTATION_TYPES = ["crossover", "adversarial_refinement", "few_shot_distillation"];
function agentNameToRole(agentName) {
  const n = agentName.toLowerCase();
  if (/(cfo|tax|finance|ke toan|accountant)/.test(n)) return "finance";
  if (/(sales|proposal|sale)/.test(n)) return "sales";
  if (/(market|ads|campaign)/.test(n)) return "marketing";
  if (/(code|dev|engineer|architect)/.test(n)) return "coding";
  if (/(video|media|content)/.test(n)) return "media";
  if (/(support|service|care)/.test(n)) return "support";
  return "general";
}
function toRecord(g, role, index) {
  return {
    agentName: role,
    generationNumber: g.generation,
    fitnessScorePercent: Math.round(g.fitness * 1e3) / 10,
    mutationType: MUTATION_TYPES[index % MUTATION_TYPES.length],
    testedPromptSnippet: g.tokens.join(" ").slice(0, 120),
    status: "active_champion"
  };
}
function getGeneticPromptData() {
  const summary2 = getPromptEvolutionSummary();
  const runs2 = getRunHistory();
  const generations = runs2.map((r2, i2) => toRecord(r2.champion, r2.role, i2));
  const averageFitnessImprovementPercent = runs2.length ? runs2.reduce((s, r2) => s + Math.max(0, r2.improvementPercent), 0) / runs2.length : 0;
  return {
    totalGenerationsEvolved: summary2.totalGenerationsEvolved,
    averageFitnessImprovementPercent: Math.round(averageFitnessImprovementPercent * 10) / 10,
    activeAgentsOptimizedCount: summary2.rolesOptimized,
    generations,
    lastEvolutionAt: summary2.lastEvolutionAt
  };
}
function evolveAgentPromptGeneration(agentName) {
  const role = agentNameToRole(agentName);
  const result = evolvePromptsForRole(role);
  return {
    success: true,
    agentName,
    newGeneration: result.champion.generation,
    achievedFitnessPercent: Math.round(result.champion.fitness * 1e3) / 10,
    mutationDiff: `T\u1ED1i \u01B0u prompt vai "${role}" qua ${result.generationsRun} th\u1EBF h\u1EC7. Fitness trung b\xECnh: ${result.initialAvgFitness.toFixed(3)} \u2192 ${result.finalAvgFitness.toFixed(3)} (+${result.improvementPercent.toFixed(1)}%).`,
    evolvedAt: (/* @__PURE__ */ new Date()).toISOString()
  };
}

// server/services/bftConsensus.ts
var import_node_perf_hooks = require("node:perf_hooks");
function computeFaultTolerance(replicaCount) {
  return Math.max(0, Math.floor((replicaCount - 1) / 3));
}
function computeQuorum(replicaCount) {
  return 2 * computeFaultTolerance(replicaCount) + 1;
}
function runPBFTLite(replicas, votes, options = {}) {
  const start = import_node_perf_hooks.performance.now();
  const n = replicas.length;
  const f = computeFaultTolerance(n);
  const quorum = computeQuorum(n);
  const majorityRatio = options.majorityRatio ?? 2 / 3;
  const weightById = new Map(replicas.map((r2) => [r2.id, Math.max(0, r2.weight)]));
  const totalWeight = replicas.reduce((s, r2) => s + Math.max(0, r2.weight), 0);
  let approveCount = 0;
  let rejectCount = 0;
  let approveWeight = 0;
  let rejectWeight = 0;
  for (const vote of votes) {
    if (!weightById.has(vote.replicaId)) continue;
    const weight = weightById.get(vote.replicaId) * Math.max(0, Math.min(1, vote.confidence));
    if (vote.value === "approve") {
      approveCount += 1;
      approveWeight += weight;
    } else {
      rejectCount += 1;
      rejectWeight += weight;
    }
  }
  const threshold = majorityRatio * totalWeight;
  let value = "no_quorum";
  if (approveCount >= quorum && approveWeight >= threshold) {
    value = "approve";
  } else if (rejectCount >= quorum && rejectWeight >= threshold) {
    value = "reject";
  }
  return {
    proposalId: options.proposalId ?? `proposal_${Date.now().toString(36)}`,
    decided: value !== "no_quorum",
    value,
    faultsTolerated: f,
    replicaCount: n,
    quorum,
    approveCount,
    rejectCount,
    approveWeight,
    rejectWeight,
    totalWeight,
    commitLatencyMs: import_node_perf_hooks.performance.now() - start,
    viewChanges: 0
  };
}
function assembleDefaultReplicas(roles = ["finance", "security", "architecture", "planner"]) {
  return roles.map((role, i2) => ({ id: `replica_${i2}_${role}`, role, weight: 1 }));
}
function deriveDemoVotes(replicas) {
  const sorted2 = [...replicas].sort((a2, b3) => a2.weight - b3.weight);
  const dissenterId = sorted2[0]?.id;
  return replicas.map((r2) => ({
    replicaId: r2.id,
    value: r2.id === dissenterId ? "reject" : "approve",
    confidence: 1
  }));
}

