async function pollEmployeeMailbox(input2) {
  const employee = getAgentEmployeeById(input2.employeeId);
  const result = { employeeId: input2.employeeId, processed: 0, replied: 0, blocked: 0, errors: [] };
  if (!employee) {
    result.errors.push("Employee not found.");
    return result;
  }
  const unread = fetchAgentMailbox(employee.roleId, { status: "unread" });
  const profiles = await WebAiSessionManager.listProfiles();
  const profile = pickWebProfile(profiles, input2.webProfileId, employee.domains);
  for (const msg of unread) {
    result.processed++;
    if (!profile) {
      result.blocked++;
      result.errors.push(`${employee.roleId}: no ready web profile available.`);
      continue;
    }
    const compliance = evaluateWebChatCompliance({
      enabled: profile.enabled,
      status: profile.status,
      termsMode: termsModeForPlatform(profile.platform)
    });
    if (!compliance.allowed) {
      result.blocked++;
      result.errors.push(`${employee.roleId}: ${compliance.reasons.join("; ")}`);
      continue;
    }
    try {
      const webResult = await executeWebAIAutomation(profile.platform, msg.body, void 0, { profileId: profile.id });
      sendA2AMessage({
        threadId: msg.threadId,
        senderRole: employee.roleId,
        recipientRole: msg.senderRole,
        messageType: "share_artifact",
        subject: `RE: ${msg.subject}`,
        body: webResult.text
      });
      markA2AMessageStatus(msg.id, employee.roleId, "completed");
      persistEmployeeOutput({
        employee,
        subject: msg.subject,
        prompt: msg.body,
        output: webResult.text,
        threadId: msg.threadId
      });
      result.replied++;
    } catch (err) {
      result.errors.push(`${employee.roleId}: ${err instanceof Error ? err.message : String(err)}`);
    }
  }
  return result;
}
async function runEmployeeShift(input2) {
  const employee = getAgentEmployeeById(input2.employeeId);
  const result = { employeeId: input2.employeeId, processed: 0, replied: 0, blocked: 0, errors: [] };
  if (!employee) {
    result.errors.push("Employee not found.");
    return result;
  }
  const unread = fetchAgentMailbox(employee.roleId, { status: "unread" });
  for (const msg of unread) {
    result.processed++;
    const task = await executeEmployeeTask({
      employeeId: input2.employeeId,
      prompt: msg.body,
      webProfileId: input2.webProfileId,
      approved: msg.approved === true
    });
    if (task.needsApproval) {
      result.blocked++;
      result.errors.push(`${employee.roleId}: tin "${msg.subject}" c\u1EA7n ng\u01B0\u1EDDi duy\u1EC7t tr\u01B0\u1EDBc khi d\xF9ng web chat.`);
      continue;
    }
    if (!task.success) {
      result.blocked++;
      result.errors.push(`${employee.roleId}: ${task.error || "failed"}`);
      continue;
    }
    sendA2AMessage({
      threadId: msg.threadId,
      senderRole: employee.roleId,
      recipientRole: msg.senderRole,
      messageType: "share_artifact",
      subject: `RE: ${msg.subject}`,
      body: task.content || ""
    });
    markA2AMessageStatus(msg.id, employee.roleId, "completed");
    persistEmployeeOutput({
      employee,
      subject: msg.subject,
      prompt: msg.body,
      output: task.content || "",
      threadId: msg.threadId
    });
    result.replied++;
  }
  return result;
}
function startEmployeeMailboxWorker(intervalMs = 6e4) {
  let running2 = false;
  const timer4 = setInterval(async () => {
    if (running2) return;
    running2 = true;
    try {
      const employees = listAgentEmployees();
      for (const employee of employees) {
        const result = await runEmployeeShift({ employeeId: employee.id });
        if (result.processed > 0) {
          console.log(`[EmployeeWorker] ${employee.name}: processed=${result.processed} replied=${result.replied} blocked=${result.blocked}`);
        }
      }
    } catch (err) {
      console.error("[EmployeeWorker] shift error:", err);
    } finally {
      running2 = false;
    }
  }, intervalMs);
  return () => clearInterval(timer4);
}

