  const userPrompt = `\u0110\u1EC0 B\xC0I (Prompt):
${input2.prompt}

K\u1EBET QU\u1EA2 C\u1EE6A AI (Output):
${input2.response}

H\xE3y ch\u1EA5m \u0111i\u1EC3m chi ti\u1EBFt.`;
  let judgeContent = "";
