    completeness: 75,
    format: 80,
    safety: 90,
    overallScore: 80,
    verdict: "PASS",
    reasoning: "Ch\u1EA5m \u0111i\u1EC3m d\u1EF1 ph\xF2ng t\u1EF1 \u0111\u1ED9ng (Heuristic baseline)",
    judgeProvider: "heuristic-baseline"
