var DOMAIN_ROLE_MAP = {
  coding: "AI Dev",
  finance: "AI CFO",
  marketing: "AI Marketer",
  sales: "AI Sales",
  media: "AI Video",
  research: "AI Research",
  general: "Chief of Staff"
};
function findBestEmployee(domain2) {
  const roleName = DOMAIN_ROLE_MAP[domain2] || "Chief of Staff";
  const employees = listAgentEmployees();
  return employees.find((e) => e.roleId === roleName) || employees[0];
}
function describeEndpoint(endpoint) {
  return `${endpoint.kind}:${endpoint.provider}${endpoint.model ? ":" + endpoint.model : ""}`;
}
async function dispatchTask(input2) {
  const domain2 = input2.domain || "general";
  const employee = findBestEmployee(domain2);
  if (!employee) throw new Error("No AI employee available.");
  const routedTo = {
    employeeId: employee.id,
    name: employee.name,
    strength: employee.strength,
    accessMethod: employee.accessMethod,
    primary: describeEndpoint(employee.primary)
  };
  if (input2.useCli && employee.primary.kind === "cli") {
    try {
      const cliResult = await runCliAgent({
        cli: employee.primary.provider,
        prompt: input2.goal
      });
      if (cliResult.success) {
        return {
          goal: input2.goal,
          domain: domain2,
          routedTo,
          result: { success: true, usedBinding: "cli", provider: employee.primary.provider, content: cliResult.output }
        };
      }
    } catch {
    }
  }
  const task = await executeEmployeeTask({ employeeId: employee.id, prompt: input2.goal, localFirst: input2.localFirst });
  return {
    goal: input2.goal,
    domain: domain2,
    routedTo,
    result: {
      success: task.success,
      usedBinding: task.usedBinding,
      provider: task.provider,
      content: task.content,
      error: task.error
    }
  };
}
function listRoutingTable() {
  return listAgentEmployees().map((e) => ({
    id: e.id,
    name: e.name,
    emoji: e.emoji,
    group: e.group,
    strength: e.strength,
    accessMethod: e.accessMethod,
    primary: describeEndpoint(e.primary),
    fallbacks: e.fallbacks.map((f) => describeEndpoint(f)),
    costTier: e.costTier
  }));
}

