var IMAGE_COST_USD = 0.039;
var MUSIC_COST_USD = 0.04;
function round2(n) {
  return Math.round(n * 100) / 100;
}
function planScriptToVideo(input2) {
  const sceneCount = Math.max(1, Math.min(12, input2.sceneCount || 6));
  const scenes = [];
  for (let i2 = 0; i2 < sceneCount; i2 += 1) {
    scenes.push({
      index: i2 + 1,
      narration: `C\u1EA3nh ${i2 + 1} v\u1EC1 ${input2.topic}.`,
      imagePrompt: `Minh h\u1ECDa ${input2.topic}, c\u1EA3nh ${i2 + 1}, phong c\xE1ch cinematic, 16:9.`,
      durationSec: 5
    });
  }
  const imagesUsd = round2(sceneCount * IMAGE_COST_USD);
  const ttsUsd = 0;
  const musicUsd = round2(MUSIC_COST_USD);
  const videoClipsUsd = input2.useVideoClips ? round2(2 * 0.05) : 0;
  return {
    id: `video_${Date.now()}`,
    title: input2.topic,
    format: input2.format || "tiktok_shorts_reels",
    scenes,
    pipeline: [
      "script: gemini free",
      `image: gemini-2.5-flash-image (${imagesUsd} USD)`,
      "tts: gemini-2.5-flash-tts (free)",
      `music: lyria (${musicUsd} USD)`,
      "assemble: ffmpeg ($0)"
    ],
    estimatedCost: {
      imagesUsd,
      ttsUsd,
      musicUsd,
      videoClipsUsd,
      totalUsd: round2(imagesUsd + ttsUsd + musicUsd + videoClipsUsd),
      currency: "USD"
    }
  };
}

