// server/services/mcpToolRunStore.ts
init_aiWorkforceLocalStore();
init_runtimePaths();
var MAX_SIGNALS = 2e3;
var store12 = createJsonFileLocalStore({
  filePath: () => resolveRuntimePathFromEnv("MCP_TOOL_RUN_STORE_FILE", "mcp_tool_run_signals.local.json"),
  emptyState: () => ({ version: 1, signals: [] }),
  normalizeState: (parsed) => {
    const candidate = parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
    return {
      version: 1,
      signals: Array.isArray(candidate.signals) ? candidate.signals.filter((signal) => Boolean(
        signal && typeof signal.toolId === "string" && typeof signal.ok === "boolean" && typeof signal.latencyMs === "number" && typeof signal.createdAt === "string"
      )).slice(-MAX_SIGNALS) : []
    };
  }
});
async function appendMCPToolRunSignal(signal) {
  await store12.mutate((state) => {
    state.signals.push({ ...signal });
    if (state.signals.length > MAX_SIGNALS) state.signals.splice(0, state.signals.length - MAX_SIGNALS);
  });
  return signal;
}
async function listMCPToolRunSignals(limit = MAX_SIGNALS) {
  const state = await store12.read();
  return state.signals.slice().sort((a2, b3) => b3.createdAt.localeCompare(a2.createdAt)).slice(0, Math.max(1, Math.min(limit, MAX_SIGNALS)));
}
async function getMCPToolRunStoreStats() {
  const signals = await listMCPToolRunSignals();
  return { total: signals.length, latestSignal: signals[0] || null, storage: await store12.stats() };
}

