function getUnifiedActivityFeed(filter2) {
  let list = [...activityFeedStore];
  if (filter2?.department && filter2.department !== "all") {
    list = list.filter((item) => item.department === filter2.department);
  }
  if (filter2?.urgency && filter2.urgency !== "all") {
    list = list.filter((item) => item.urgency === filter2.urgency);
  }
  return list.slice(0, filter2?.limit || 50);
}
function resolveActivityItem(id) {
  const item = activityFeedStore.find((i2) => i2.id === id);
  if (item) {
    item.resolved = true;
    return true;
  }
  return false;
}

