function queryKnowledgeRAG(query, categoryFilter, topK = 3) {
  const startTime = Date.now();
  const normalizedQuery = query.toLowerCase().trim();
  const terms2 = normalizedQuery.split(/\s+/).filter((t2) => t2.length > 1);
  const scoredDocs = CORPUS.filter((doc) => !categoryFilter || doc.category === categoryFilter).map((doc) => {
    let score = 0;
    const textToSearch = `${doc.title} ${doc.content} ${doc.tags.join(" ")}`.toLowerCase();
    if (textToSearch.includes(normalizedQuery)) score += 50;
    for (const term of terms2) {
      if (doc.title.toLowerCase().includes(term)) score += 15;
      if (doc.tags.some((t2) => t2.toLowerCase().includes(term))) score += 10;
      const matches = textToSearch.split(term).length - 1;
      score += matches * 2;
    }
    return { ...doc, relevanceScore: score };
  }).sort((a2, b3) => (b3.relevanceScore || 0) - (a2.relevanceScore || 0));
  const topDocuments = scoredDocs.slice(0, topK);
  const formattedContextPack = topDocuments.map((doc, idx) => `[TR\xCD TH\u1EE8C #${idx + 1} | ${doc.title} (${doc.category})]
${doc.content}
`).join("\n---\n\n");
  const totalTokensEstimate = Math.ceil(formattedContextPack.length / 4);
  const latency = Date.now() - startTime;
  const maxScore = topDocuments[0]?.relevanceScore || 0;
  const confidence = Math.min(1, Math.max(0.2, maxScore / 50));
  return {
    query,
    topDocuments,
    formattedContextPack,
    totalTokensEstimate,
    retrievalLatencyMs: latency,
    confidence
  };
}
async function addKnowledgeDocument(doc) {
  const newDoc = {
    ...doc,
    id: `kb_${(0, import_node_crypto58.randomUUID)().slice(0, 8)}`,
    updatedAt: (/* @__PURE__ */ new Date()).toISOString()
  };
  CORPUS.unshift(newDoc);
  await appendAuditEvent({
    actor: "knowledge-rag-pipeline",
    workspace: "Knowledge-Library",
    action: "knowledge.document_added",
    target: newDoc.id,
    risk: "LOW",
    status: "executed",
    summary: `Th\xEAm tri th\u1EE9c m\u1EDBi: ${newDoc.title} (${newDoc.category})`,
    evidence: { docId: newDoc.id, tags: newDoc.tags }
  }).catch(() => void 0);
  return newDoc;
}
function listKnowledgeDocuments(category) {
  if (category) return CORPUS.filter((d) => d.category === category);
  return [...CORPUS];
}

