async function recordTaskLearning(input2) {
  const existing = INSIGHTS.find((i2) => i2.topic.toLowerCase() === input2.topic.toLowerCase() && i2.agentRole === input2.agentRole);
  if (existing) {
    existing.occurrences += 1;
    existing.confidence = Math.min(1, existing.confidence + 0.05);
    existing.lessonSummary = input2.lessonSummary;
    existing.actionableRule = input2.actionableRule;
    return existing;
  }
  const insight = {
    id: `learn_${(0, import_node_crypto59.randomUUID)().slice(0, 8)}`,
    source: input2.source,
    agentRole: input2.agentRole,
    topic: input2.topic,
    lessonSummary: input2.lessonSummary,
    actionableRule: input2.actionableRule,
    confidence: input2.confidence ?? 0.85,
    occurrences: 1,
    promotedToKnowledgeBase: false,
    createdAt: (/* @__PURE__ */ new Date()).toISOString()
  };
  INSIGHTS.unshift(insight);
  if (insight.confidence >= 0.9 && !insight.promotedToKnowledgeBase) {
    await addKnowledgeDocument({
      title: `[T\u1EF1 H\u1ECDc] ${insight.topic} (${insight.agentRole})`,
      category: "agent_guidelines",
      content: `${insight.lessonSummary}

Quy t\u1EAFc h\xE0nh \u0111\u1ED9ng: ${insight.actionableRule}`,
      tags: ["auto-learned", insight.agentRole.toLowerCase().replace(/\s+/g, "-"), "continuous-learning"],
      source: `Continuous Learning Engine (${insight.source})`
    }).catch(() => void 0);
    insight.promotedToKnowledgeBase = true;
  }
  await publishSystemEvent(
    "agent.auto_repair_completed",
    "continuous-learning-engine",
    `\u0110\xFAc k\u1EBFt tri th\u1EE9c m\u1EDBi t\u1EEB ${input2.agentRole}: ${input2.topic}`,
    { insightId: insight.id, confidence: insight.confidence }
  ).catch(() => void 0);
  return insight;
}
function listLearningInsights() {
  return [...INSIGHTS];
}
function getLearningDashboard() {
  return {
    totalInsights: INSIGHTS.length,
    promotedToKB: INSIGHTS.filter((i2) => i2.promotedToKnowledgeBase).length,
    avgConfidence: (INSIGHTS.reduce((s, i2) => s + i2.confidence, 0) / (INSIGHTS.length || 1)).toFixed(2),
    totalOccurrences: INSIGHTS.reduce((s, i2) => s + i2.occurrences, 0),
    topAgents: ["AI Sales", "AI Dev", "AI CFO"]
  };
}

