function getHarvestedKnowledgeInsights() {
  return harvestedStore;
}
function harvestKnowledgeFromCompletedTask(input2) {
  const confidence = input2.confidenceScore ?? 0.94;
  const isAutoApproved = confidence >= 0.9;
  const newInsight = {
    id: `harv_${Date.now()}`,
    sourceTask: input2.sourceTask,
    sourceAgent: input2.sourceAgent,
    category: input2.category,
    title: input2.title,
    distilledLesson: input2.distilledLesson,
    actionableRules: input2.actionableRules,
    confidenceScore: confidence,
    status: isAutoApproved ? "auto_approved" : "pending_review",
    harvestedAt: (/* @__PURE__ */ new Date()).toISOString()
  };
  if (isAutoApproved) {
    const docId = `kb_harvested_${Date.now()}`;
    const doc = {
      id: docId,
      title: input2.title,
      category: input2.category,
      content: `${input2.distilledLesson}

Quy t\u1EAFc th\u1EF1c thi:
${input2.actionableRules.map((r2, i2) => `${i2 + 1}. ${r2}`).join("\n")}`,
      tags: ["auto-harvested", input2.category, input2.sourceAgent.toLowerCase().replace(/\s+/g, "-")],
      source: `AI Auto-Harvest: ${input2.sourceAgent}`,
      updatedAt: (/* @__PURE__ */ new Date()).toISOString()
    };
    addKnowledgeDocument(doc);
    newInsight.targetKnowledgeId = docId;
  }
  harvestedStore.unshift(newInsight);
  publishSystemEvent({
    eventType: "knowledge.harvested",
    source: "AutonomousKnowledgeHarvester",
    department: "operate",
    payload: {
      insightId: newInsight.id,
      title: newInsight.title,
      confidence: newInsight.confidenceScore,
      autoApproved: isAutoApproved
    }
  });
  return newInsight;
}
function approveHarvestedInsight(id) {
  const insight = harvestedStore.find((h2) => h2.id === id);
  if (!insight) {
    return { success: false };
  }
  insight.status = "auto_approved";
  const docId = `kb_approved_${Date.now()}`;
  const doc = {
    id: docId,
    title: insight.title,
    category: insight.category,
    content: `${insight.distilledLesson}

Quy t\u1EAFc th\u1EF1c thi:
${insight.actionableRules.map((r2, i2) => `${i2 + 1}. ${r2}`).join("\n")}`,
    tags: ["auto-harvested", "human-verified", insight.category],
    source: `AI Auto-Harvest (Approved): ${insight.sourceAgent}`,
    updatedAt: (/* @__PURE__ */ new Date()).toISOString()
  };
  addKnowledgeDocument(doc);
  insight.targetKnowledgeId = docId;
  return { success: true, insight };
}
function triggerAutoHarvestBatch() {
  const sample = harvestKnowledgeFromCompletedTask({
    sourceTask: "T\u1EF1 \u0111\u1ED9ng s\u1EEDa l\u1ED7i xung \u0111\u1ED9t CORS v\xE0 Session Keep-Alive",
    sourceAgent: "AI System Self-Healing Doctor",
    category: "developer_architecture",
    title: "C\u01A1 ch\u1EBF Ph\u1EE5c h\u1ED3i K\u1EBFt n\u1ED1i SSE v\xE0 WebSocket trong Tr\xECnh duy\u1EC7t Desktop",
    distilledLesson: "Khi SSE timeout qu\xE1 15s, client c\u1EA7n chuy\u1EC3n sang Polling Adaptive Exponential Backoff v\u1EDBi \u0111\u1ED9 tr\u1EC5 kh\u1EDFi t\u1EA1o 2.5s.",
    actionableRules: [
      "Kh\xF4ng reconnect li\xEAn t\u1EE5c d\u01B0\u1EDBi 1s \u0111\u1EC3 tr\xE1nh qu\xE1 t\u1EA3i backend",
      "L\u01B0u tr\u1EEF telemetry event buffer t\u1ED1i thi\u1EC3u 50 items g\u1EA7n nh\u1EA5t"
    ],
    confidenceScore: 0.95
  });
  return {
    harvestedCount: 1,
    autoCommittedCount: sample.status === "auto_approved" ? 1 : 0
  };
}

