// server/services/dormant/ai-knowledgeRouter.ts
function successResponse4(res, data) {
  return res.json({ success: true, ...data });
}
function errorResponse4(res, err, status2 = 500) {
  const message = err instanceof Error ? err.message : String(err);
  return res.status(status2).json({ success: false, error: message });
}
function registerAiKnowledgeRoutes(app) {
  app.post("/api/dormant/agent-memory/save", async (req, res) => {
    try {
      const { category, topic, insight, recommendedAction, confidence, tags } = req.body || {};
      if (!topic || !insight || !recommendedAction) {
        return res.status(400).json({ success: false, error: "Missing topic, insight, or recommendedAction." });
      }
      const lesson = await addLessonLearned({
        category: category || "general",
        topic,
        insight,
        recommendedAction,
        confidence,
        tags
      });
      return successResponse4(res, { lesson });
    } catch (err) {
      return errorResponse4(res, err);
    }
  });
  app.get("/api/dormant/agent-memory/search", async (req, res) => {
    try {
      const query = String(req.query.q || "");
      const results = await searchLongTermMemory(query);
      return successResponse4(res, { results });
    } catch (err) {
      return errorResponse4(res, err);
    }
  });
  app.post("/api/dormant/knowledge/rag-query", (req, res) => {
    try {
      const { query, category, topK } = req.body || {};
      if (!query) return res.status(400).json({ success: false, error: "Missing search query." });
      const result = queryKnowledgeRAG(String(query), category, Number(topK || 3));
      return successResponse4(res, { result });
    } catch (err) {
      return errorResponse4(res, err);
    }
  });
  app.get("/api/dormant/knowledge/documents", (req, res) => {
    try {
      const category = req.query.category;
      const documents = listKnowledgeDocuments(category);
      return successResponse4(res, { documents, count: documents.length });
    } catch (err) {
      return errorResponse4(res, err);
    }
  });
  app.post("/api/dormant/knowledge/documents", async (req, res) => {
    try {
      const { title, category, content, tags, source: source2 } = req.body || {};
      if (!title || !content) return res.status(400).json({ success: false, error: "Missing title or content." });
      const doc = await addKnowledgeDocument({ title, category: category || "company_sop", content, tags: tags || [], source: source2 || "User" });
      return successResponse4(res, { document: doc });
    } catch (err) {
      return errorResponse4(res, err);
    }
  });
  app.get("/api/dormant/learning/dashboard", (_req, res) => {
    try {
      const dashboard = getLearningDashboard();
      const insights = listLearningInsights();
      return successResponse4(res, { dashboard, insights });
    } catch (err) {
      return errorResponse4(res, err);
    }
  });
  app.post("/api/dormant/learning/record", async (req, res) => {
    try {
      const { source: source2, agentRole, topic, lessonSummary, actionableRule, confidence } = req.body || {};
      if (!agentRole || !topic || !lessonSummary) {
        return res.status(400).json({ success: false, error: "Missing required learning payload fields." });
      }
      const insight = await recordTaskLearning({ source: source2 || "agent_run", agentRole, topic, lessonSummary, actionableRule: actionableRule || lessonSummary, confidence });
      return successResponse4(res, { insight });
    } catch (err) {
      return errorResponse4(res, err);
    }
  });
  app.get("/api/dormant/rbac/policies", (_req, res) => {
    try {
      const policies = listRolePolicies();
      return successResponse4(res, { policies });
    } catch (err) {
      return errorResponse4(res, err);
    }
  });
  app.post("/api/dormant/rbac/check-access", (req, res) => {
    try {
      const { role, workspace } = req.body || {};
      if (!role || !workspace) return res.status(400).json({ success: false, error: "Missing role or workspace." });
      const allowed = canAccessWorkspace(role, workspace);
      return successResponse4(res, { allowed, role, workspace });
    } catch (err) {
      return errorResponse4(res, err);
    }
  });
  app.get("/api/dormant/knowledge/harvested", (_req, res) => {
    try {
      return successResponse4(res, { insights: getHarvestedKnowledgeInsights() });
    } catch (err) {
      return errorResponse4(res, err);
    }
  });
  app.post("/api/dormant/knowledge/harvest-batch", (_req, res) => {
    try {
      const result = triggerAutoHarvestBatch();
      return successResponse4(res, result);
    } catch (err) {
      return errorResponse4(res, err);
    }
  });
  app.post("/api/dormant/knowledge/approve-harvest", (req, res) => {
    try {
      const { id } = req.body || {};
      if (!id) {
        return res.status(400).json({ success: false, error: "Missing 'id'." });
      }
      const result = approveHarvestedInsight(id);
      return successResponse4(res, result);
    } catch (err) {
      return errorResponse4(res, err);
    }
  });
  app.get("/api/dormant/rag-search/index", (_req, res) => {
    try {
      return successResponse4(res, getSemanticSearchData());
    } catch (err) {
      return errorResponse4(res, err);
    }
  });
  app.post("/api/dormant/rag-search/query", (req, res) => {
    try {
      const { query, corpus } = req.body || {};
      if (!query) return res.status(400).json({ success: false, error: "Missing 'query'." });
      return successResponse4(res, semanticSearch(query, corpus ?? "all"));
    } catch (err) {
      return errorResponse4(res, err);
    }
  });
  app.get("/api/dormant/knowledge-bridge/overview", (_req, res) => {
    try {
      return successResponse4(res, notionObsidianKnowledgeBridgeEngine.getBridgeOverview());
    } catch (err) {
      return errorResponse4(res, err);
    }
  });
  app.post("/api/dormant/knowledge-bridge/sync", (_req, res) => {
    try {
      return successResponse4(res, notionObsidianKnowledgeBridgeEngine.triggerBiDirectionalSync());
    } catch (err) {
      return errorResponse4(res, err);
    }
  });
}

