function convertCurrency(amount, from2, to) {
  const fromRate = FX_RATES.find((r2) => r2.currencyCode === from2)?.rateToVnd || 1;
  const toRate = FX_RATES.find((r2) => r2.currencyCode === to)?.rateToVnd || 1;
  const inVnd = amount * fromRate;
  const converted = inVnd / toRate;
  return {
    convertedAmount: Math.round(converted * 100) / 100,
    appliedRate: Math.round(fromRate / toRate * 1e4) / 1e4,
    formattedText: `${amount.toLocaleString()} ${from2} = ${(Math.round(converted * 100) / 100).toLocaleString()} ${to}`
  };
}

