function calculateCrossBorderTax(amountUsd, countryCode) {
  const rule = vatRulesStore.find((r2) => r2.countryCode === countryCode) || vatRulesStore[0];
  const taxRate = rule.reverseChargeApplicable ? 0 : rule.vatGstRatePercent;
  const tax = Math.round(amountUsd * taxRate / 100);
  publishSystemEvent({
    eventType: "finance.cross_border_tax_calculated",
    source: "GlobalVatReverseChargeEngine",
    department: "finance",
    payload: {
      amountUsd,
      country: rule.countryName,
      reverseCharge: rule.reverseChargeApplicable
    }
  });
  return {
    success: true,
    baseAmountUsd: amountUsd,
    taxAmountUsd: tax,
    totalInvoiceAmountUsd: amountUsd + tax,
    taxSummary: rule.reverseChargeApplicable ? `\xC1p d\u1EE5ng C\u01A1 ch\u1EBF T\u1EF1 t\xEDnh thu\u1EBF Reverse Charge: Kh\xE1ch h\xE0ng ${rule.countryName} t\u1EF1 k\xEA khai thu\u1EBF GST/VAT t\u1EA1i n\u01B0\u1EDBc s\u1EDF t\u1EA1i (0% t\u1EA1i ngu\u1ED3n).` : `Kh\u1EA5u tr\u1EEB thu\u1EBF nh\xE0 th\u1EA7u FCT/VAT t\u1EA1i ngu\u1ED3n: ${rule.vatGstRatePercent}% theo quy \u0111\u1ECBnh hi\u1EC7n h\xE0nh.`
  };
}

