  const avgWin = Math.round(pricingTiersStore.reduce((s, t2) => s + t2.winProbabilityScore, 0) / pricingTiersStore.length);
  return {
    tiers: pricingTiersStore,
    averageMarginRetention: avgMargin,
    overallWinProbability: avgWin
  };
