function calculateDynamicQuote(input2) {
  const prepayDiscount = input2.annualPrepay ? 15 : 5;
  const offeredPrice = Math.round(input2.dealSizeVnd * (1 - prepayDiscount / 100));
  publishSystemEvent({
    eventType: "sales.dynamic_quote_calculated",
    source: "DynamicRepricingEngine",
    department: "sales",
    payload: {
      industry: input2.industry,
      offeredPrice
    }
  });
  return {
    offeredPriceVnd: offeredPrice,
    discountPercentage: prepayDiscount,
    contractMonths: input2.annualPrepay ? 12 : 1,
    reasoning: `Chi\u1EBFt kh\u1EA5u ${prepayDiscount}% \xE1p d\u1EE5ng cho g\xF3i tr\u1EA3 tr\u01B0\u1EDBc 1 n\u0103m ng\xE0nh ${input2.industry} nh\u1EB1m t\u1ED1i \u01B0u h\xF3a v\xF2ng quay ti\u1EC1n m\u1EB7t (Cash Flow Velocity).`
  };
}

