async function runRevenueLeakReconciliationRobot() {
  const now = /* @__PURE__ */ new Date();
  const allInvoices = listBusinessEntities("invoice", 500);
  const overdueInvoices = [];
  let totalOverdueAmount = 0;
  for (const inv of allInvoices) {
    if (inv.data.isPaymentReceipt) continue;
    const isPaid = inv.data.status === "paid" || inv.data.isPaid === true;
    if (!isPaid) {
      const amount = Number(inv.data.amount || inv.data.totalAmount || 0);
      const createdAt = new Date(inv.createdAt || now);
      const diffDays = Math.floor((now.getTime() - createdAt.getTime()) / (1e3 * 3600 * 24));
      if (diffDays >= 14) {
        const customerName = String(inv.data.customerName || inv.data.client || "Qu\xFD kh\xE1ch");
        const invoiceCode = String(inv.data.invoiceCode || inv.id);
        const reminderDraft = `K\xEDnh g\u1EEDi ${customerName},

LedgerFlow Studio xin g\u1EEDi l\u1EDDi ch\xE0o tr\xE2n tr\u1ECDng.
H\xF3a \u0111\u01A1n ${invoiceCode} (S\u1ED1 ti\u1EC1n: ${amount.toLocaleString("vi-VN")} \u0111) hi\u1EC7n \u0111\xE3 qu\xE1 h\u1EA1n thanh to\xE1n ${diffDays} ng\xE0y. Qu\xFD kh\xE1ch vui l\xF2ng qu\xE9t m\xE3 VietQR \u0111\xEDnh k\xE8m ho\u1EB7c chuy\u1EC3n kho\u1EA3n \u0111\u1EC3 ho\xE0n t\u1EA5t \u0111\u1ED1i so\xE1t ch\u1EE9ng t\u1EEB.

Tr\xE2n tr\u1ECDng c\u1EA3m \u01A1n!`;
        overdueInvoices.push({
          invoiceId: inv.id,
          invoiceCode,
          customerName,
          amount,
          daysOverdue: diffDays,
          reminderDraft
        });
        totalOverdueAmount += amount;
      }
    }
  }
  const suggestedActions = [];
  if (overdueInvoices.length > 0) {
    suggestedActions.push(`C\xF3 ${overdueInvoices.length} kho\u1EA3n n\u1EE3 qu\xE1 h\u1EA1n (${totalOverdueAmount.toLocaleString("vi-VN")} \u0111). Duy\u1EC7t g\u1EEDi email nh\u1EAFc n\u1EE3 t\u1EF1 \u0111\u1ED9ng.`);
  } else {
    suggestedActions.push("T\u1EA5t c\u1EA3 c\xE1c kho\u1EA3n ph\u1EA3i thu (TK 131) \u0111\u1EC1u \u0111ang trong h\u1EA1n an to\xE0n.");
  }
  const report = {
    id: `rev_leak_${Date.now()}`,
    totalOverdueAmount,
    overdueInvoicesCount: overdueInvoices.length,
    unreconciledAdvancesAmount: 0,
    overdueInvoices,
    suggestedActions,
    createdAt: now.toISOString()
  };
  if (overdueInvoices.length > 0) {
    upsertBusinessEntity({
      id: `task_debt_collect_${Date.now()}`,
      type: "task",
      data: {
        title: `Thu h\u1ED3i n\u1EE3 qu\xE1 h\u1EA1n: ${overdueInvoices.length} h\xF3a \u0111\u01A1n (${totalOverdueAmount.toLocaleString("vi-VN")} \u0111)`,
        needsApproval: true,
        status: "pending_approval",
        report
      },
      source: "ai"
    });
  }
  return report;
}

